-- PostgreSQL query. Reference CSV was generated by executing the equivalent logic on the SQLite validation DB.

WITH line_versions AS (
 SELECT l.*,h.supplier_id AS supplier_id,h.currency AS order_currency,h.order_dttm_msk AS order_dttm_msk,i.item_name,i.category,u.base_uom,u.factor_to_base,
        ROW_NUMBER() OVER (PARTITION BY l.order_id,l.line_no ORDER BY l.updated_at DESC,l.source_row_no DESC) rn
 FROM core_po_line_version l
 JOIN core_po_header h ON h.order_id=l.order_id
 LEFT JOIN core_dim_item i ON i.item_id=l.item_id
 LEFT JOIN core_dim_uom u ON u.uom_code=l.uom_code
),
selected AS (
 SELECT * FROM line_versions
 WHERE rn=1 AND lower(COALESCE(status,''))<>'cancelled'
   AND planned_delivery_date::date >= '2026-04-01' AND planned_delivery_date::date < '2026-07-01'
   AND factor_to_base > 0
),
priced AS (
 SELECT s.*,
        CASE WHEN upper(order_currency) IN ('RUB','RUR') THEN 1.0 ELSE fx.rate_to_rub END AS fx_rate,
        qty*factor_to_base AS qty_base,
        price / factor_to_base * (CASE WHEN upper(order_currency) IN ('RUB','RUR') THEN 1.0 ELSE fx.rate_to_rub END) AS unit_price_rub_base,
        qty*price*(CASE WHEN upper(order_currency) IN ('RUB','RUR') THEN 1.0 ELSE fx.rate_to_rub END) AS purchase_amount_rub
 FROM selected s
 LEFT JOIN core_dim_fx_rate fx ON fx.rate_date::date=s.order_dttm_msk::date AND fx.currency=s.order_currency
),
supplier_item AS (
 SELECT item_id,item_name,category,supplier_id,
        SUM(qty_base) AS qty_base,
        SUM(qty_base*unit_price_rub_base)/NULLIF(SUM(qty_base),0) AS weighted_price_rub_base,
        SUM(purchase_amount_rub) AS purchase_amount_rub
 FROM priced
 WHERE fx_rate IS NOT NULL AND unit_price_rub_base IS NOT NULL
 GROUP BY item_id,item_name,category,supplier_id
),
comparisons AS (
 SELECT a.*,
        (SELECT AVG(weighted_price_rub_base) FROM (
           SELECT b.supplier_id,b.weighted_price_rub_base,
                  ROW_NUMBER() OVER (ORDER BY b.weighted_price_rub_base) rn,
                  COUNT(*) OVER () n
           FROM supplier_item b
           WHERE b.item_id=a.item_id AND b.supplier_id<>a.supplier_id
        ) med
        WHERE rn IN ((n+1)/2,(n+2)/2)) AS median_other_suppliers
 FROM supplier_item a
),
scored AS (
 SELECT *,100.0*(weighted_price_rub_base-median_other_suppliers)/NULLIF(median_other_suppliers,0) AS deviation_pct
 FROM comparisons
 WHERE median_other_suppliers IS NOT NULL
)
SELECT item_id,item_name,category,supplier_id,
       ROUND(weighted_price_rub_base,2) AS our_price_rub_per_base_uom,
       ROUND(median_other_suppliers,2) AS median_other_suppliers_rub_per_base_uom,
       ROUND(deviation_pct,2) AS deviation_pct,
       ROUND(purchase_amount_rub,2) AS purchase_amount_rub
FROM scored
WHERE ABS(deviation_pct)>15
ORDER BY ABS(deviation_pct) DESC
LIMIT 15;
